//! Independent-oracle parity test (luts.md §2 + §5, issue #7).
//!
//! The fixture (`tests/oracle_fixtures.json`) is generated by
//! `tools/lut_oracle.py` — a from-scratch barycentric implementation that
//! shares no code with this crate. CI regenerates the fixture and diffs it
//! (`--verify`), so the oracle cannot silently drift from the Rust engine.
//!
//! This test proves, per fixture LUT and sample:
//! * the `.cube` text parses into the same lattice the oracle used
//!   (a transposed/misread layout would fail the sampled values),
//! * tetrahedral (3D) / piecewise-linear (1D) results agree ≤ 1e-6,
//! * clamp flags agree exactly.

use melography_lut::cube::{parse_cube, CubeKind};
use melography_lut::sample;
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    luts: Vec<FixtureLut>,
}

#[derive(Deserialize)]
struct FixtureLut {
    name: String,
    kind: String,
    size: u32,
    domain_min: [f32; 3],
    domain_max: [f32; 3],
    cube_text: String,
    samples: Vec<FixtureSample>,
}

#[derive(Deserialize)]
struct FixtureSample {
    #[serde(rename = "in")]
    input: [f32; 3],
    out: [f32; 3],
    clamped: [bool; 3],
}

#[test]
fn cpu_matches_independent_oracle_within_1e_6() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/oracle_fixtures.json");
    let bytes = match std::fs::read(path) {
        Ok(b) => b,
        Err(e) => panic!(
            "fixture missing/unreadable ({e}); regenerate with:\n\
             \tpython3 tools/lut_oracle.py crates/lut/tests/oracle_fixtures.json"
        ),
    };
    let fixture: Fixture = serde_json::from_slice(&bytes)
        .expect("fixture JSON schema — regenerate with tools/lut_oracle.py");

    assert!(
        fixture.luts.len() >= 5,
        "fixture shrank — expected the 5 canonical LUTs"
    );
    let mut total_samples = 0usize;
    let mut worst_abs: f32 = 0.0;
    let mut worst_report = String::new();

    for lut_fix in &fixture.luts {
        let lut = parse_cube(&lut_fix.cube_text)
            .unwrap_or_else(|e| panic!("oracle cube_text must parse ({:?}): {e:?}", lut_fix.name));
        assert_eq!(lut.size, lut_fix.size, "{}: size", lut_fix.name);
        assert_eq!(
            lut.domain_min, lut_fix.domain_min,
            "{}: domain_min",
            lut_fix.name
        );
        assert_eq!(
            lut.domain_max, lut_fix.domain_max,
            "{}: domain_max",
            lut_fix.name
        );
        let expect_kind = match lut_fix.kind.as_str() {
            "3d" => CubeKind::Lut3d,
            "1d" => CubeKind::Lut1d,
            other => panic!("unknown fixture kind {other:?}"),
        };
        assert_eq!(lut.kind, expect_kind, "{}: kind", lut_fix.name);

        for s in &lut_fix.samples {
            let (out, clamped) = sample(&lut, s.input);
            for c in 0..3 {
                let d = (out[c] - s.out[c]).abs();
                if d > worst_abs {
                    worst_abs = d;
                    worst_report = format!(
                        "{}: in={:?} ch={c} rust={:.9} oracle={:.9}",
                        lut_fix.name, s.input, out[c], s.out[c]
                    );
                }
                assert!(
                    d <= 1e-6,
                    "{}: in={:?} ch={c} rust={:?} oracle={:?} (|Δ|={d:e})",
                    lut_fix.name,
                    s.input,
                    out,
                    s.out
                );
            }
            assert_eq!(
                [clamped.r, clamped.g, clamped.b],
                s.clamped,
                "{}: clamp flags for in={:?}",
                lut_fix.name,
                s.input
            );
            total_samples += 1;
        }
    }
    // Visible in CI logs (tests run with -- --nocapture): the real margin.
    println!(
        "oracle parity: {total_samples} samples across {} LUTs — worst |Δ| = {worst_abs:.3e} ({worst_report})",
        fixture.luts.len()
    );
    assert!(total_samples >= 600);
}
